  1	import java.util.ArrayList;
  2	import java.util.Arrays;
  3	import java.util.Comparator;
  4	import java.util.List;
  5	import java.util.PriorityQueue;
  6	
  7	public class HuffmanCoding {
  8	    private static final String SINGLE_SYMBOL_CODE = "0";
  9	    private static final Comparator<Node> NODE_ORDER =
 10	            Comparator.comparingInt((Node node) -> node.frequency)
 11	                    .thenComparingInt(node -> node.sortOrder);
 12	
 13	    private static final class Node {
 14	        private final int frequency;
 15	        private final int sortOrder;
 16	        private final int symbolIndex;
 17	        private final Node left;
 18	        private final Node right;
 19	
 20	        private Node(int frequency, int symbolIndex) {
 21	            this(frequency, symbolIndex, symbolIndex, null, null);
 22	        }
 23	
 24	        private Node(Node left, Node right) {
 25	            this(
 26	                    left.frequency + right.frequency,
 27	                    Math.min(left.sortOrder, right.sortOrder),
 28	                    -1,
 29	                    left,
 30	                    right
 31	            );
 32	        }
 33	
 34	        private Node(int frequency, int sortOrder, int symbolIndex, Node left, Node right) {
 35	            this.frequency = frequency;
 36	            this.sortOrder = sortOrder;
 37	            this.symbolIndex = symbolIndex;
 38	            this.left = left;
 39	            this.right = right;
 40	        }
 41	
 42	        private boolean isLeaf() {
 43	            return left == null && right == null;
 44	        }
 45	    }
 46	
 47	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
 48	        validateInputs(symbols, frequencies);
 49	        if (symbols.isEmpty()) {
 50	            return new ArrayList<>();
 51	        }
 52	
 53	        PriorityQueue<Node> queue = buildLeafQueue(frequencies);
 54	        Node root = buildTree(queue);
 55	        return buildCodes(root, symbols.length());
 56	    }
 57	
 58	    private static void validateInputs(String symbols, int[] frequencies) {
 59	        if (symbols == null) {
 60	            throw new IllegalArgumentException("symbols must not be null");
 61	        }
 62	        if (frequencies == null) {
 63	            throw new IllegalArgumentException("frequencies must not be null");
 64	        }
 65	        if (symbols.length() != frequencies.length) {
 66	            throw new IllegalArgumentException("symbols and frequencies must be the same length");
 67	        }
 68	    }
 69	
 70	    private static PriorityQueue<Node> buildLeafQueue(int[] frequencies) {
 71	        PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
 72	        for (int i = 0; i < frequencies.length; i++) {
 73	            queue.add(new Node(frequencies[i], i));
 74	        }
 75	        return queue;
 76	    }
 77	
 78	    private static Node buildTree(PriorityQueue<Node> queue) {
 79	        while (queue.size() > 1) {
 80	            Node left = queue.poll();
 81	            Node right = queue.poll();
 82	            queue.add(new Node(left, right));
 83	        }
 84	        return queue.peek();
 85	    }
 86	
 87	    private static ArrayList<String> buildCodes(Node root, int symbolCount) {
 88	        String[] codesBySymbol = new String[symbolCount];
 89	        collectCodes(root, new StringBuilder(), codesBySymbol);
 90	        return new ArrayList<>(Arrays.asList(codesBySymbol));
 91	    }
 92	
 93	    private static void collectCodes(Node node, StringBuilder path, String[] codesBySymbol) {
 94	        if (node == null) {
 95	            return;
 96	        }
 97	
 98	        if (node.isLeaf()) {
 99	            codesBySymbol[node.symbolIndex] =
100	                    path.length() == 0 ? SINGLE_SYMBOL_CODE : path.toString();
101	            return;
102	        }
103	
104	        path.append('0');
105	        collectCodes(node.left, path, codesBySymbol);
106	        path.deleteCharAt(path.length() - 1);
107	
108	        path.append('1');
109	        collectCodes(node.right, path, codesBySymbol);
110	        path.deleteCharAt(path.length() - 1);
111	    }
112	
113	    private static void printCodes(List<String> codes) {
114	        System.out.print(String.join(" ", codes));
115	    }
116	
117	    public static void main(String[] args) {
118	        String symbols = "abcdef";
119	        int[] frequencies = {5, 9, 12, 13, 16, 45};
120	        ArrayList<String> codes = huffmanCodes(symbols, frequencies);
121	        printCodes(codes);
122	    }
123	}

