12	    private static void shouldGenerateExpectedExampleCodes() {
13	        assertListEquals(
14	                Arrays.asList("0", "100", "101", "1100", "1101", "111"),
15	                HuffmanCoding.huffmanCodes("abcdef", new int[]{5, 9, 12, 13, 16, 45}),
