20	    private static void shouldHandleSingleSymbol() {
21	        assertListEquals(
22	                Arrays.asList("0"),
23	                HuffmanCoding.huffmanCodes(new int[]{7}),
24	                "single symbol should be encoded as 0"
25	        );
