36	    private static void shouldRejectMismatchedInputLengths() {
37	        assertThrows(
38	                IllegalArgumentException.class,
39	                () -> HuffmanCoding.huffmanCodes("ab", new int[]{1}),
40	                "mismatched symbols and frequencies should be rejected"
41	        );
42	    }
