50	    private static void assertThrows(
51	            Class<? extends Throwable> expectedType,
52	            ThrowingRunnable action,
53	            String message
54	    ) {
55	        try {
56	            action.run();
57	        } catch (Throwable error) {
58	            if (expectedType.isInstance(error)) {
59	                return;
60	            }
61	            throw new AssertionError(message + ": expected " + expectedType.getSimpleName()
62	                    + " but got " + error.getClass().getSimpleName(), error);
63	        }
64	
65	        throw new AssertionError(message + ": expected " + expectedType.getSimpleName());
66	    }
67	
68	    @FunctionalInterface
69	    private interface ThrowingRunnable {
70	        void run();
71	    }
